import argparse


def main(argv=None):
    ap = argparse.ArgumentParser()
    ap.add_argument("--verbose", action="store_true", help="print debug lines")
    a = ap.parse_args(argv)
    if a.verbose:
        print("debug: starting")
    print("hello")


if __name__ == "__main__":
    main()
